create_order_preview.code:
import (
	"fmt"
)

resp, err := client.OrderPreviews().CreateOrderPreview(ctx, map[string]any{
	"customer_id":   512,
	"delivery_type": "shipping",
	"products": []any{
		map[string]any{"product_id": 101, "quantity": 2},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
order := resp.Map().(map[string]any)["order"].(map[string]any)
session := order["session"].(map[string]any)
totals := order["totals"].(map[string]any)
fmt.Println(session["session_id"], session["status"], session["expires_at"])
fmt.Println(totals["sub_total"], totals["shipping_cost"], totals["grand_total"], totals["due"])

